  let last = -1;
  for (let j = 0; j < J; j++) if (D(k, j)) last = j;
  if (last < J - 500) whiteFrom.push({ k, from: last + 1 });
}
console.log('(a) diagonals white from an index onward (within j <', J, '):', whiteFrom.map((w) => `${w.k}@${w.from}`).join(' '));

