for (const { k, from } of whiteFrom) {
  const m = k - 1;
  if (m < 0) continue;
  const N = Math.max(from - 1, 0);
  for (const q of [1, 2, 4, 8, 16]) {
    let ones = 0;
    for (let j = 0; j < q; j++) ones += D(m, N + j + 2);
    if (q === 16) console.log(`      white diagonal ${k}: N=${N}, parity over q=16 is ${ones % 2 ? 'odd' : 'even'}`);
  }
}

